                  AdminApparatusScopePicker(
                    apparatus: widget.apparatus,
                    selected: _selected,
                    onChanged: (apparatusId, checked) {
                      setState(() {
                        if (checked) {
                          _selected.add(apparatusId);
                        } else {
                          _selected.remove(apparatusId);
                        }
                      });
                    },
                  ),
                ],
              ),
            ),
            SafeArea(
              top: false,
